<div><label for="title">Titulo</label><input id="title" name="title" value="{{ old('title', $item->title ?? '') }}" required></div>
<div><label for="summary">Resumen</label><textarea id="summary" name="summary" rows="2">{{ old('summary', $item->summary ?? '') }}</textarea></div>
<div><label for="body">Texto principal</label><textarea id="body" name="body" rows="7" required>{{ old('body', $item->body ?? '') }}</textarea></div>
