<div class="fields-2"><div><label for="external_kind">Tipo de enlace</label><select id="external_kind" name="external_kind"><option value="">Sin enlace</option><option value="youtube">YouTube</option><option value="link">Otro sitio</option></select></div><div><label for="external_url">URL</label><input id="external_url" name="external_url" type="url" value="{{ old('external_url') }}" placeholder="https://"></div></div>
<div><label for="resource_notes">Descripcion o transcripcion de los recursos</label><textarea id="resource_notes" name="resource_notes" rows="5" placeholder="Describe la imagen o pega la transcripcion del video. Este texto sera consultable por el chatbot.">{{ old('resource_notes') }}</textarea></div>
